'use strict';
Object.assign(Business,{
 statuses:{DRAFT:'草稿',PENDING:'待审核',CONFIRMED:'已确认',REJECTED:'已驳回'},
 async receipts(){const r=await API.request('/receipts');this.open('入库管理',`<div class="business-toolbar"><button id="new-receipt" class="button primary" ${this.can('receipt:write')?'':'disabled'}>单笔 / 多捆入库</button><button id="import-receipt" class="button secondary" ${this.importReceipt&&this.can('receipt:write')?'':'disabled'}>Excel 批量导入</button><label>状态<select id="receipt-status"><option value="">全部状态</option>${Object.entries(this.statuses).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label></div><p>最近 200 张授权单据。只有独立审核人员确认后才计入库存；不提供已确认单据删除。</p><div id="receipt-list"></div>`);const draw=()=>{$('receipt-list').innerHTML='<div class="business-table"><table><thead><tr><th>单号</th><th>客户</th><th>状态</th><th>捆数</th><th>操作人</th><th>操作</th></tr></thead><tbody>'+r.items.filter(d=>!$('receipt-status').value||d.status===$('receipt-status').value).map(d=>`<tr><td>${esc(d.code)}</td><td>${esc(d.customer_name)}</td><td>${this.statuses[d.status]}</td><td>${d.line_count}</td><td>${esc(d.creator_name)}</td><td><button class="detail-button" data-receipt="${d.id}">详情 / 审核</button></td></tr>`).join('')+'</tbody></table></div>';$('receipt-list').querySelectorAll('[data-receipt]').forEach(b=>b.onclick=()=>this.receiptDetail(b.dataset.receipt).catch(e=>notify(e.message)));};$('receipt-status').onchange=draw;$('new-receipt').onclick=()=>this.receiptEditor().catch(e=>notify(e.message));$('import-receipt').onclick=()=>this.importReceipt().catch(e=>notify(e.message));draw();},
 async receiptDetail(id){const r=await API.request('/receipts/'+id),selfException=CurrentUser.role_code==='production_dept'&&AppConfig.environment==='test'&&AppConfig.productionReceiptSelfReviewEnabled,canReview=(![r.created_by,r.submitted_by].includes(CurrentUser.id)||selfException),d=await this.load(),lookup=(type,id)=>d[type].find(x=>x.id===id)?.code||id;this.open('入库单 '+r.code,`<p>状态：${this.statuses[r.status]} · 版本 ${r.version} · 创建人 ${esc(r.creator_name||r.created_by)}<br>提交人：${esc(r.submitted_by||'历史未记录')}<br>测试期自审：${r.self_review_exception?'已使用':selfException?'已启用（仅生产入库）':'未使用'}<br>确认时间：${esc(r.confirmed_at||'尚未确认')}<br>备注：${esc(r.remark||'—')}${r.rejection_reason?'<br>驳回原因：'+esc(r.rejection_reason):''}</p><div class="business-toolbar">${['DRAFT','REJECTED'].includes(r.status)&&this.can('receipt:write')&&(r.created_by===CurrentUser.id||CurrentUser.role_code==='admin')?'<button class="button primary" id="edit-receipt">修改草稿</button><button class="button secondary" data-receipt-action="submit">提交审核</button>':''}${r.status==='PENDING'&&this.can('receipt:review')&&canReview?'<button class="button primary" data-receipt-action="confirm">确认入库（整单）</button><button class="button secondary" data-receipt-action="reject">驳回</button>':''}</div>${r.status==='PENDING'&&!canReview?'<p>请由另一位授权审核人员确认，不能自行审核。</p>':''}${r.status==='PENDING'&&this.can('receipt:review')&&canReview?'<label>驳回原因（驳回时必填）<input id="reject-reason" maxlength="500"></label>':''}<p id="receipt-action-error" class="error" role="alert"></p><div class="business-table"><table><thead><tr><th>捆包号</th><th>批次</th><th>捆包片数</th><th>生产日期</th><th>入库时间</th><th>毛重（吨）</th><th>包装（吨）</th><th>净重（吨）</th><th>货位</th><th>备注</th></tr></thead><tbody>${r.lines.map(l=>`<tr><td>${esc(l.bundle_no)}</td><td>${esc(lookup('batches',l.batch_id))}</td><td>${l.sheets_per_bundle??'未录入'}</td><td>${esc(l.production_date)}</td><td>${esc(new Date(l.inbound_at).toLocaleString('zh-CN'))}</td><td>${esc(Tonnes.format(l.gross_weight))}</td><td>${esc(Tonnes.format(l.packaging_weight))}</td><td>${esc(Tonnes.format(l.net_weight))}</td><td>${esc(lookup('locations',l.location_id))}</td><td>${esc(l.remark)}</td></tr>`).join('')}</tbody></table></div>`);if($('edit-receipt'))$('edit-receipt').onclick=()=>this.receiptEditor(r).catch(e=>notify(e.message));document.querySelectorAll('[data-receipt-action]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await API.request('/receipts/'+id+'/'+b.dataset.receiptAction,{method:'POST',body:{version:r.version,...(b.dataset.receiptAction==='reject'?{reason:$('reject-reason').value}:{})}});await this.receiptDetail(id);await render();notify('入库单状态已更新');}catch(e){$('receipt-action-error').textContent=e.message;b.disabled=false;}});},
 async receiptEditor(r={}){const d=await this.load();let lines=r.lines?.map(l=>({...l}))||[{}];const localTime=value=>{const dt=value?new Date(value):new Date();return new Date(dt-dt.getTimezoneOffset()*60000).toISOString().slice(0,16);};this.open(r.id?'修改入库草稿':'新建入库草稿',`<form id="receipt-editor" class="user-form"><div class="form-grid"><label>项目<select name="project_id" ${r.id?'disabled':''}>${this.options(d.projects,r.project_id,'name')}</select></label><label>货权客户<select name="customer_id">${this.options(d.customers.filter(c=>c.active),r.customer_id,'name')}</select></label></div><label>单据备注<input name="remark" value="${esc(r.remark||'')}" maxlength="1000"></label><p>毛重单位：吨，最多四位小数。每捆固定扣包0.002500吨（2.5kg），服务端计算净重。历史未知毛重不可推算，编辑旧草稿须重新核实毛重。入库时间按浏览器本地时间输入，提交时保留时区。操作人由登录会话记录。</p><div class="business-table"><table class="receipt-line-table"><thead><tr><th>捆包编号</th><th>生产批次</th><th>生产日期</th><th>入库时间</th><th>毛重（吨）</th><th>包装（吨）</th><th>净重（吨）</th><th>货位</th><th>备注</th><th></th></tr></thead><tbody id="receipt-editor-lines"></tbody></table></div><button class="button secondary" type="button" id="add-receipt-line">增加一捆</button><p class="error" id="receipt-save-error" role="alert"></p><button class="button primary" type="submit">保存草稿（不增加库存）</button></form>`);
 const read=()=>[...document.querySelectorAll('#receipt-editor-lines tr')].map(tr=>Object.fromEntries([...tr.querySelectorAll('[data-field]')].map(x=>[x.dataset.field,x.value])));
 const draw=()=>{$('receipt-editor-lines').innerHTML=lines.map((l,i)=>`<tr><td><input data-field="bundle_no" aria-label="捆包编号" required maxlength="80" value="${esc(l.bundle_no||'')}"></td><td><select data-field="batch_id" aria-label="生产批次">${this.options(d.batches.filter(x=>x.active),l.batch_id)}</select></td><td><input data-field="production_date" aria-label="生产日期" type="date" required value="${esc(l.production_date||'')}"></td><td><input data-field="inbound_at" aria-label="入库时间" type="datetime-local" required value="${esc(l.inbound_at?.includes('Z')?localTime(l.inbound_at):l.inbound_at||localTime())}"></td><td><input data-field="gross_weight" aria-label="毛重（吨）" inputmode="decimal" required pattern="[0-9]+([.][0-9]{1,4})?" value="${esc(l.gross_weight||'')}"></td><td>0.002500</td><td><output data-net-preview>输入毛重后计算</output></td><td><select data-field="location_id" aria-label="货位">${this.options(d.locations.filter(x=>x.active),l.location_id)}</select></td><td><input data-field="remark" aria-label="捆包备注" maxlength="500" value="${esc(l.remark||'')}"></td><td><button type="button" class="text-button" data-remove-line="${i}">移除</button></td></tr>`).join('');document.querySelectorAll('#receipt-editor-lines tr').forEach(tr=>{[...tr.cells].forEach((td,i)=>td.dataset.label=document.querySelectorAll('.receipt-line-table th')[i]?.textContent||'');const input=tr.querySelector('[data-field="gross_weight"]'),out=tr.querySelector('[data-net-preview]');const update=()=>{try{if(!/^\d+(\.\d{1,4})?$/.test(input.value))throw Error();const [a,b='']=input.value.split('.'),n=BigInt(a)*1000000n+BigInt(b.padEnd(6,'0'))-2500n;out.textContent=n>0n?`${n/1000000n}.${String(n%1000000n).padStart(6,'0')}`:'毛重须大于包装重量';}catch{out.textContent='待输入有效毛重';}};input.oninput=update;update();});document.querySelectorAll('[data-remove-line]').forEach(b=>b.onclick=()=>{lines=read();lines.splice(Number(b.dataset.removeLine),1);draw();});};draw();$('add-receipt-line').onclick=()=>{lines=read();lines.push({});draw();};$('receipt-editor').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const header=Object.fromEntries(new FormData(e.target)),body={...header,origin:r.origin||'MANUAL',lines:read().map(l=>({...l,inbound_at:new Date(l.inbound_at).toISOString()}))};if(r.id){delete body.project_id;body.version=r.version;}const result=await API.request('/receipts'+(r.id?'/'+r.id:''),{method:r.id?'PATCH':'POST',body});await this.receiptDetail(result.id);notify('草稿已保存，尚未计入库存');}catch(err){$('receipt-save-error').textContent=err.message;e.submitter.disabled=false;}};}
});
Business.menu=function(){this.open('业务工作台',`<div class="business-menu"><button id="open-masters" class="button secondary">基础资料</button><button id="open-receipts" class="button secondary">入库管理</button><button id="open-allocations" class="button secondary" ${this.allocations?'':'disabled'}>客户备货${this.allocations?'':'（开发中）'}</button></div>`);$('open-masters').onclick=()=>this.masters().catch(e=>notify(e.message));$('open-receipts').onclick=()=>this.receipts().catch(e=>notify(e.message));if(this.allocations)$('open-allocations').onclick=()=>this.allocations().catch(e=>notify(e.message));};
const receiptNav=document.querySelector('[data-info="入库管理"]');if(receiptNav){receiptNav.removeAttribute('data-info');receiptNav.querySelector('small').remove();receiptNav.onclick=()=>Business.receipts().catch(e=>notify(e.message));}
